const raw = String($input.first().json.sql_query || '').trim();
if (!raw) throw new Error('sql_query vazio');

// Remove ; final e espacos
let clean = raw.replace(/;+\s*$/, '').trim();

// Bloqueia multiplas instrucoes
if (/;/.test(clean)) {
  throw new Error('Multiplas instrucoes nao sao permitidas');
}

// Deve comecar com SELECT ou WITH
if (!/^(select|with)\b/i.test(clean)) {
  throw new Error('Apenas SELECT/WITH e permitido');
}

// Strip de comentarios SQL (-- ... e /* ... */) para checar palavras escondidas
const stripped = clean
  .replace(/--[^\n\r]*/g, ' ')
  .replace(/\/\*[\s\S]*?\*\//g, ' ');

// Lista negra de tokens (\b garante token inteiro)
const forbidden = /\b(insert|update|delete|drop|alter|truncate|create|grant|revoke|copy|vacuum|reindex|cluster|comment|call|merge|lock|set|begin|commit|rollback|do|listen|notify|prepare|execute|deallocate|refresh|security|function|procedure|trigger|policy|role|database|schema|table|view|sequence|extension|publication|subscription|tablespace|user|password)\b/i;
const m = stripped.match(forbidden);
if (m) {
  throw new Error('Palavra-chave SQL proibida: ' + m[0]);
}

// GUARDRAIL DE VOLUME: varredura da base bruta de apontamentos
const usaBaseBruta = /\bmv_base_apontamentos\b/i.test(stripped);
if (usaBaseBruta) {
  const temRecorte = /\bwhere\b/i.test(stripped) && /\bano\b/i.test(stripped);
  if (!temRecorte) {
    throw new Error('Consulta a mv_base_apontamentos exige WHERE com filtro de ano (e de preferencia semana ou mes). Use as tools de indicador agregadas (ind_* / indm_*).');
  }
  if (!/\bgroup\s+by\b/i.test(stripped)) {
    const mLim = stripped.match(/\blimit\s+(\d+)/i);
    if (!mLim || parseInt(mLim[1], 10) > 50) {
      throw new Error('Consulta linha a linha em mv_base_apontamentos exige LIMIT de no maximo 50, ou use GROUP BY para agregar.');
    }
  }
}

// LIMIT obrigatorio (rough check)
if (!/\blimit\b/i.test(stripped)) {
  clean = clean + ' LIMIT 200';
} else {
  // Teto global de 200 linhas
  clean = clean.replace(/\blimit\s+(\d+)/i, (full, n) => (parseInt(n, 10) > 200 ? 'LIMIT 200' : full));
}

return [{ json: { sql_query: clean } }];
